UPDATE talk_parts SET sort_order = 1, phase = 'OPENING + IDENTIFY', row_name = 'Meet our robot + Mission strategy', goal = 'Clear evidence of mission strategy', core_values = 0, speaker = 'Isla', say = '["This is our robot!","It''s low and wide with extra bracing, so it doesn''t tip and it turns accurately.","We built three copies of the base, so we can test three attachments at once and have a spare.","Our strategy: try every mission. We have an attachment for all 15.","A match is only 150 seconds, so we group nearby missions into nine runs.","Fynn and I timed them with a stopwatch: Missions 6, 7 and 11 together take only 17 seconds."]', show_what = 'The robot (hold it up) · then: Fynn + Isla''s timing notes, run plan in the app', photos = '["11-8-mission-timing-notes.webp"]', check_note = 'The notebook never wrote down WHY three copies. Is "test three at once + a spare" really your reason? Say your real one.' WHERE id = 13 AND talk = 'rd';
UPDATE talk_parts SET sort_order = 2, phase = 'IDENTIFY + DESIGN', row_name = 'Use of resources + All members contributed', goal = 'Clear use of building or coding resources to support the strategy · Clear evidence that all team members contributed ideas', core_values = 1, speaker = 'Adeline', say = '["We code in Pybricks, using Python.","I made a program template that every mission starts from, so they all set up the motors and wheels the same way.","We also used the official rulebook, Coach CJ, and our team app.","Everyone contributed ideas.","On September 19, all six of us built or programmed something. Nolan had the idea to put Missions 2 and 3 on one attachment.","And we build on each other''s work: Fynn started the Forest Elder attachment, Isla finished it, and Adeline rebuilt it."]', show_what = 'Laptop: Pybricks with the template · then: "Who''s been doing what" in the app', photos = '[]', check_note = NULL WHERE id = 15 AND talk = 'rd';
UPDATE talk_parts SET sort_order = 3, phase = 'DESIGN + CREATE', row_name = 'Skills in all members + Attachments', goal = 'Clear evidence of building and coding skills in all team members · Clear explanation of innovative attachments and their purpose', core_values = 0, speaker = 'Weston', say = '["Every one of us builds AND codes.","I built the base, then my first attachment for Mission 14, then programmed Mission 9.","Thea was a builder and wrote her first program for Mission 12. Nolan builds attachments and programmed Missions 2 and 3.","Our attachments do more than one mission per trip.","Our 2-and-3 attachment knocks the seeds loose and flips the rock. One attachment does Missions 8 and 9 at the big tree, and Nolan built one for 6, 7 and 11.","Our mascot even rides along for Mission 13!"]', show_what = 'Mission 14 attachment · then: The 2+3 attachment, the 8+9 attachment, the mascot', photos = '["11-2-mission-14.jpg","11-2-mission-2-3.jpg","11-2-mission-8-9.jpg"]', check_note = NULL WHERE id = 17 AND talk = 'rd';
UPDATE talk_parts SET sort_order = 4, phase = 'CREATE + ITERATE', row_name = 'Code / sensors + Testing', goal = 'Clear explanation of innovative code and/or sensor use · Clear evidence of repeated testing of robot and code', core_values = 0, speaker = 'Fynn', say = '["Our base has no room for color sensors.","So our code uses the gyro in the hub to drive straight and turn exactly, and measures distance with wheel rotations.","It knows our wheels are 49.5 millimeters wide and 160 millimeters apart. Ports B and F run the attachments.","We test over and over.","Mission 14 worked 5 out of 5 times, and so did Missions 2 and 3. Missions 4 and 5 worked 4 out of 5.","On November 8, Isla and I tested every mission and listed what needs work, like Mission 15''s yellow arm."]', show_what = 'Laptop: a mission program · then: Test results in the app (Robot Design page)', photos = '[]', check_note = 'Did you count any more tries since Nov 8? Add them: more "5 out of 5" numbers make this row stronger.' WHERE id = 19 AND talk = 'rd';
UPDATE talk_parts SET sort_order = 5, phase = 'ITERATE + COMMUNICATE', row_name = 'Improvements + Process & lessons learned', goal = 'Clear evidence of improvements based on testing · Detailed explanation of process and lessons learned', core_values = 1, speaker = 'Thea', say = '["Our code changed 18 times this season.","The Mission 4 program changed at four practices in a row, grew from 19 lines to 57, and got faster.","We rebuilt the Forest Elder attachment because [[why?]], and split Mission 12 into two parts to fit our runs.","Our process: build, code, test, fix, repeat.","Lesson one: time real runs. Our first plan was all guesses and way over 150 seconds.","Lesson two: combine missions to save trips. Lesson three: write everything down, so we know who did what and every change."]', show_what = 'Code history grid in the app (Coding page) · then: Engineering notebook / app', photos = '[]', check_note = 'The notebook never says WHY the Forest Elder (Mission 12) was rebuilt on Oct 12. Judges love "we saw ___, changed ___, now ___."' WHERE id = 21 AND talk = 'rd';
UPDATE talk_parts SET sort_order = 6, phase = 'COMMUNICATE + CLOSING', row_name = 'Pride & enthusiasm + Next steps + thank you', goal = 'Team clearly shows pride or enthusiasm', core_values = 1, speaker = 'Nolan', say = '["We are proud of how far we came!","In August we had one robot base. Now every mission has an attachment, and one run takes only 7 seconds.","My favorite moment was [[your favorite moment]].","Next, we''ll fix Mission 15''s yellow arm, finish timing our last runs, and keep counting our tries.","Thank you! Do you have any questions for us?","(Everyone:) We are the Rooted Warriors!"]', show_what = 'Big smiles! · then: Everyone together', photos = '[]', check_note = NULL WHERE id = 23 AND talk = 'rd';
DELETE FROM talk_parts WHERE talk = 'rd' AND id IN (14, 16, 18, 20, 22, 24);
